import { z } from "zod";

/**
 * The intake form. Keys match the field names in public/forms/rhino-intake-template.pdf
 * (generated by tools/make_intake_template.py), so a saved intake can be written straight into the PDF.
 */
export const TEXT_FIELDS = [
  "date", "agent", "lead_source",
  "full_name", "dob", "dl_number", "dl_state",
  "spouse_name", "spouse_dob", "spouse_dl_number", "spouse_dl_state",
  "phone1", "phone2", "email", "address1", "address2",
  "family_children", "origin", "time_in_us", "grade_score",
  "current_carrier", "expiration_date", "how_long_insured",
  "business_name", "experience_years", "dot", "mc", "ein", "ubi",
  "truck_insurance", "truck_renewal_date", "truck_how_long",
  "eld_provider", "trailer_equipment", "notes",
] as const;

/** Single-choice groups: form key -> option value -> PDF checkbox name. */
export const CHOICES = {
  priority: { High: "priority_high", Normal: "priority_normal", Low: "priority_low" },
  type: { Personal: "type_personal", Commercial: "type_commercial" },
  housing: { Rent: "housing_rent", Own: "housing_own", Share: "housing_share" },
  insured30: { Yes: "insured30_yes", No: "insured30_no" },
  payment: { EFT: "pay_eft", Card: "pay_card" },
  cargo: { "100k": "cargo_100k", "250k": "cargo_250k", Other: "cargo_other" },
  trailer: { Reefer: "trailer_reefer", "Dry van": "trailer_dry_van", Flatbed: "trailer_flatbed", Other: "trailer_other" },
  length: { "45'": "len_45", "48'": "len_48", "53'": "len_53" },
  radius: { Local: "radius_local", "Long (500+ mi)": "radius_long" },
  ifta: { Yes: "ifta_yes", No: "ifta_no" },
} as const;

export const DRIVER_FIELDS = ["name", "dob", "dl", "years_licensed", "marital", "occupation", "education", "relationship"] as const;
export const VEHICLE_FIELDS = ["year", "make", "model", "vin", "annual_miles", "driver", "ownership"] as const;
export const VIOLATION_FIELDS = ["driver", "date", "type"] as const;
export const ROWS = 4;

const str = z.string().trim().max(300).default("");
const rec = <K extends string>(keys: readonly K[]) =>
  z.object(Object.fromEntries(keys.map((k) => [k, str])) as Record<K, typeof str>);

export const intakeSchema = z.object({
  text: rec(TEXT_FIELDS).extend({ notes: z.string().trim().max(2000).default("") }),
  choice: z.object(
    Object.fromEntries(Object.keys(CHOICES).map((k) => [k, str])) as Record<keyof typeof CHOICES, typeof str>,
  ),
  drivers: z.array(rec(DRIVER_FIELDS).extend({ ddc: z.boolean().default(false), gs: z.boolean().default(false) })).length(ROWS),
  vehicles: z.array(rec(VEHICLE_FIELDS).extend({ liability_only: z.enum(["", "Yes", "No"]).default("") })).length(ROWS),
  violations: z.array(rec(VIOLATION_FIELDS)).length(ROWS),
});

export type IntakeData = z.infer<typeof intakeSchema>;

export function emptyIntake(): IntakeData {
  const blank = Array.from({ length: ROWS }, () => ({}));
  return intakeSchema.parse({ text: {}, choice: {}, drivers: blank, vehicles: blank, violations: blank });
}

/** Reads stored JSON, tolerating older or partial shapes. */
export function parseIntake(raw: unknown): IntakeData {
  const base = emptyIntake() as unknown as Record<string, unknown>;
  const r = (raw ?? {}) as Record<string, unknown>;
  const rows = (k: string) => {
    const given = Array.isArray(r[k]) ? (r[k] as unknown[]) : [];
    return Array.from({ length: ROWS }, (_, i) => given[i] ?? {});
  };
  const res = intakeSchema.safeParse({
    text: r.text ?? {}, choice: r.choice ?? {},
    drivers: rows("drivers"), vehicles: rows("vehicles"), violations: rows("violations"),
  });
  return res.success ? res.data : (base as unknown as IntakeData);
}

/** A VIN is 17 characters and never contains I, O or Q. */
export const isValidVin = (vin: string) => /^[A-HJ-NPR-Z0-9]{17}$/i.test(vin.trim());
